/// <summary>
/// Something that happened to this character, in its own telling. Not a claim about the world and never
/// checked as one: `source` says where a proposal came from, for the operator reading it, and nothing
/// downstream reads it as evidence — see `persona.story.ts` for why that is the load-bearing difference
/// from a fact
/// </summary>
public sealed record PersonaStory
{
    [JsonPropertyName("id")]
    public required string Id { get; init; }

    /// <summary>A short handle. Never spoken; what this list is read by and what a proposal names</summary>
    [JsonPropertyName("title")]
    public required string Title { get; init; }

    /// <summary>The telling itself, in the character's voice. Already speakable, because the floor reads it as it stands</summary>
    [JsonPropertyName("story")]
    public required string Story { get; init; }

    /// <summary>`active` can be told. `rejected` outlives the pass that proposed it, or the same catalogue proposes it forever</summary>
    [JsonPropertyName("state")]
    public required PersonaStoryState2 State { get; init; }

    /// <summary>Who says so. `model` is the enrichment pass writing from what the station already holds</summary>
    [JsonPropertyName("origin")]
    public required PersonaStoryOrigin Origin { get; init; }

    /// <summary>Where a proposal came from, in the station's own words. Absent for anything an operator wrote</summary>
    [JsonPropertyName("source")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Source { get; init; }

    /// <summary>An `anecdote` is told whole, an `arc` a part at a time, a `bit` is a running joke with no end</summary>
    [JsonPropertyName("kind")]
    public required PersonaStoryKind Kind { get; init; }

    /// <summary>What it has picked up since, in every state</summary>
    [JsonPropertyName("details")]
    public required List<PersonaStoryDetail> Details { get; init; }

    /// <summary>The parts an arc is told in, in order and in every state. Empty for the other two kinds</summary>
    [JsonPropertyName("beats")]
    public required List<PersonaStoryBeat> Beats { get; init; }

    /// <summary>Absent means never told, which is what puts it at the front of the rotation</summary>
    [JsonPropertyName("lastToldAt")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? LastToldAt { get; init; }

    /// <summary>How often it has gone out, which changes how the model is asked to tell it</summary>
    [JsonPropertyName("timesTold")]
    public required long TimesTold { get; init; }

    [JsonPropertyName("createdAt")]
    public required string CreatedAt { get; init; }
}

/// <summary>
