/// <summary>
/// What importing a file WOULD do, worked out against this station and written nowhere.
///
/// The same code the import itself runs, so what this reports is what will happen rather than a second
/// opinion about it. It answers two questions an operator cannot get from the file alone: which
/// characters are new here and which would be rewritten, and what this station cannot honour about them
/// </summary>
public sealed record PersonaImportPlan
{
    /// <summary>What the file said it was. Reported rather than enforced: this repo edits migrations in place, so a version stamp cannot promise a shape, and the shapes are what was actually validated</summary>
    [JsonPropertyName("format")]
    public required string Format { get; init; }

    /// <summary>The station it was taken from, when it said</summary>
    [JsonPropertyName("station")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Station { get; init; }

    /// <summary>When it was taken, when it said</summary>
    [JsonPropertyName("takenAt")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? TakenAt { get; init; }

    /// <summary>About the FILE rather than any one character in it</summary>
    [JsonPropertyName("notices")]
    public required List<PersonaImportNotice> Notices { get; init; }

    [JsonPropertyName("personas")]
    public required List<PersonaImportEntry> Personas { get; init; }
}

